-- IMEI Search: explicit QC values and immutable, paginated Reports corrections.
DO $imei_details_install$ BEGIN EXECUTE $ddl$
do $$begin if public.get_imei_activity_journey_version()is distinct from '20261109-imei-activity-1'or public.get_accounts_imei_speed_version()is distinct from '20261113-accounts-imei-speed-1'then raise exception 'Verify IMEI Activity and Accounts IMEI Speed first.';end if;if to_regprocedure('public.get_imei_qc_corrections_version()')is not null then if public.get_imei_qc_corrections_version()is distinct from '20261114-imei-qc-corrections-1'then raise exception 'Existing IMEI QC/correction integrity needs review.';end if;end if;end;$$;
create or replace function greenloop_private.itc_value(k text,v jsonb,names boolean)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare x text;begin
 if v is null or v='null'then return 'null';end if;
 if k='full_workflow'and jsonb_typeof(v)='string'then return to_jsonb(regexp_replace(v#>>'{}',';?\s*audit\s+[a-f0-9-]{36}','','i'));end if;
 if k='supplier_id'then select concat_ws(' ',supplier_code,case when names then company_name end)into x from public.suppliers where id::text=v#>>'{}';return to_jsonb(coalesce(x,'Not recorded'));end if;
 if k='receiving_batch_id'then select batch_number||case when planned_quantity is not null then '-('||planned_quantity||')'else ''end into x from public.receiving_batches where id::text=v#>>'{}';return to_jsonb(coalesce(x,'Not recorded'));end if;
 if k in('inspected_by','reviewed_by','assigned_by','issued_by','received_by','handed_over_by')then select full_name into x from public.user_profiles where id::text=v#>>'{}';return to_jsonb(coalesce(x,'Not recorded'));end if;
 if k='assigned_technician_roster_id'then select full_name into x from public.technician_roster where id::text=v#>>'{}';return to_jsonb(coalesce(x,'Not recorded'));end if;
 if k~'(_id|_by)$'then return to_jsonb('Recorded reference'::text);end if;
 if k~'(_at|_date)$'and jsonb_typeof(v)='string'then begin return to_jsonb(to_char((v#>>'{}')::timestamptz at time zone 'Asia/Dubai','DD Mon YYYY'));exception when invalid_datetime_format or datetime_field_overflow then return v;end;end if;
 if jsonb_typeof(v)in('string','number','boolean')then return v;end if;
 if jsonb_typeof(v)='array'and not exists(select 1 from jsonb_array_elements(v)a where jsonb_typeof(a)not in('string','number','boolean','null'))then select string_agg(a#>>'{}',', 'order by n)into x from jsonb_array_elements(v)with ordinality z(a,n);return to_jsonb(coalesce(x,''));end if;
 return to_jsonb('Recorded details changed'::text);
end;$$;
create or replace function greenloop_private.itc_changes(before_values jsonb,after_values jsonb,section_name text,names boolean,prices boolean)returns jsonb language sql stable security definer set search_path=pg_catalog,public as $$
 select coalesce(jsonb_agg(jsonb_build_object('key',k,'section',section_name,'field',case k when 'imei_1'then 'IMEI 1'when 'imei_2'then 'IMEI 2'when 'storage_gb'then 'GB'when 'battery_health'then 'Initial BH'when 'final_battery_health'then 'Final BH'when 'gc_grade'then 'GL Grade'when 'initial_grade'then 'GL Grade'when 'gl_grade'then 'GL Grade'when 'supplier_grade'then 'Supplier Grade'when 'original_grade'then 'Supplier Grade'when 'final_grade'then 'Final Grade'when 'supplier_id'then 'Supplier'when 'receiving_batch_id'then 'Stock / Batch'when 'full_workflow'then 'Workflow correction'else initcap(replace(k,'_',' '))end,'old',greenloop_private.itc_value(k,before_values->k,names),'new',greenloop_private.itc_value(k,after_values->k,names))order by k),'[]')from(select key k from jsonb_object_keys(coalesce(before_values,'{}'))key union select key from jsonb_object_keys(coalesce(after_values,'{}'))key)x
 where before_values->k is distinct from after_values->k and(names or k!~*'(supplier|customer).*name')and(prices or k!~*'(cost|price|amount|value)')and k not in('payload_hash','request_id','revision','created_by','updated_by','device_number','job_number','device_id','job_id');$$;
create or replace function greenloop_private.itc_history(dev uuid,p_offset integer,p_limit integer)returns jsonb language sql stable security definer set search_path=pg_catalog,public as $$
 with access as materialized(select coalesce(public.get_my_partner_name_access(),false)names,coalesce(public.has_page_capability_v1('parts','view'),false)prices),audits as materialized(
 select 'data:'||h.id id,h.changed_at at,h.changed_by actor,h.change_reason reason,
 greenloop_private.itc_changes(coalesce((select jsonb_object_agg(key,value->'old')from jsonb_each(case when jsonb_typeof(h.changed_fields)='object'then h.changed_fields else '{}'::jsonb end)where jsonb_typeof(value)='object'),'{}'),coalesce((select jsonb_object_agg(key,value->'new')from jsonb_each(case when jsonb_typeof(h.changed_fields)='object'then h.changed_fields else '{}'::jsonb end)where jsonb_typeof(value)='object'),'{}'),'IMEI details',a.names,a.prices)changes
 from public.data_change_history h cross join access a where h.device_id=dev and not(h.changed_fields?'full_workflow'and exists(select 1 from greenloop_private.workflow_correction_audit w where w.device_id=dev and position(w.id::text in(h.changed_fields->'full_workflow'->>'new'))>0))
 union all
 select 'workflow:'||w.id,w.changed_at,w.actor,w.reason,coalesce((select jsonb_agg(c order by n,c->>'key')from jsonb_array_elements(w.changes)with ordinality z(x,n)cross join lateral jsonb_array_elements(greenloop_private.itc_changes(greenloop_private.wf_public_values(x->>'kind',x->'before',a.prices),greenloop_private.wf_public_values(x->>'kind',x->'after',a.prices),initcap(replace(x->>'kind','_',' ')),a.names,a.prices))c),'[]')
 from greenloop_private.workflow_correction_audit w cross join access a where w.device_id=dev
 ),shaped as materialized(select a.id,a.at occurred_at,coalesce(u.full_name,'Recorded user')actor,a.reason,a.changes from audits a left join public.user_profiles u on u.id=a.actor),payload as(select coalesce(jsonb_agg(to_jsonb(s)order by occurred_at desc,id),'[]')all_rows from shaped s)
 select jsonb_build_object('version','20261114-imei-qc-corrections-1','offset',p_offset,'limit',p_limit,'total',jsonb_array_length(all_rows),'snapshot',md5(all_rows::text),'rows',coalesce((select jsonb_agg(x order by n)from jsonb_array_elements(all_rows)with ordinality z(x,n)where n>p_offset and n<=p_offset+p_limit),'[]'))from payload;
$$;
create or replace function greenloop_private.itc_enrich(data jsonb,dev uuid,latest_job uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare d public.devices%rowtype;j public.jobs%rowtype;q record;begin
 select *into d from public.devices where id=dev and deleted_at is null;if d.id is null then return data;end if;select *into j from public.jobs where id=latest_job and device_id=dev and deleted_at is null;
 select *into q from(select f.final_grade grade,f.final_battery_health bh,f.final_battery_health_unavailable unavailable,f.inspected_at at,'Final QC / B-DEPT'::text source from public.final_qc_inspections f where f.job_id=j.id and f.device_id=dev and not(coalesce(f.routed_to_frame,false)and position('Initial QC direct route to Frame'in coalesce(f.notes,''))>0)
 union all select x.final_grade,x.battery_health,x.battery_health_unavailable,x.ready_at,'Initial QC direct Ready release'from greenloop_private.qc_direct_ready x where x.job_id=j.id and x.device_id=dev)f order by at desc,source limit 1;
 data:=jsonb_set(data,'{rows}',coalesce((select jsonb_agg(r||jsonb_build_object('report_correction',r->>'stage'='correction'or r->>'status'='admin_correction'or exists(select 1 from public.device_events e where e.device_id=dev and r->>'id'='event:'||e.id and e.event_type in('imei_data_corrected','imei_record_corrected','full_workflow_corrected','bulk_imei_corrected','available_stock_corrected','restricted_data_corrected','restricted_record_corrected')))order by n)from jsonb_array_elements(data->'rows')with ordinality x(r,n)),'[]'));
 return jsonb_set(data,'{device}',data->'device'||jsonb_build_object('initial_battery_health',d.battery_health,'initial_battery_health_unavailable',d.battery_health_unavailable,'supplier_grade',coalesce(nullif(j.supplier_grade,''),d.original_grade),'gl_grade',d.gc_grade,'final_battery_health',q.bh,'final_battery_health_unavailable',q.unavailable,'final_grade',q.grade,'final_qc_source',q.source))||jsonb_build_object('qc_details_version','20261114-imei-qc-corrections-1','report_corrections',greenloop_private.itc_history(dev,0,50));
end;$$;
do $patch$declare sig text:='greenloop_private.ia_read(text)';old text;updated text;before_hash text;t record;c record;begin
 old:=pg_get_functiondef(sig::regprocedure);before_hash:=md5(old);updated:=old;
 if position('greenloop_private.itc_enrich'in old)=0 then
 updated:=regexp_replace(updated,$p$return\s+(greenloop_private\s*\.\s*chaman_journey\s*\(\s*jsonb_set\s*\(\s*data\s*,\s*'\{rows\}'\s*,\s*output\s*\)\s*\|\|\s*jsonb_build_object\s*\(\s*'activity_presentation_version'\s*,\s*'20261109-imei-activity-1'\s*\)\s*,\s*p_imei\s*\))\s*;$p$,$v$return greenloop_private.itc_enrich(\1,d.id,latest.id);$v$);
 if updated=old or position('greenloop_private.itc_enrich'in updated)=0 then raise exception 'IMEI activity read boundary changed. Review before installing.';end if;execute updated;
 end if;
 -- Reseal only receipts whose existing reviewed before-hash matches.
 for c in select *from(values('identity','hash'),('identity','before_hash'),('identity','definition_hash'),('object_identity','definition_hash'),('function_identity','definition_hash'))x(idcol,hashcol)loop
  for t in select cls.oid::regclass::text name from pg_class cls where cls.relnamespace='greenloop_private'::regnamespace and cls.relkind='r'and cls.relname like '%_installation'and exists(select 1 from pg_attribute where attrelid=cls.oid and attname=c.idcol and atttypid='text'::regtype)and exists(select 1 from pg_attribute where attrelid=cls.oid and attname=c.hashcol and atttypid='text'::regtype)loop
   execute format('update %s set %I=md5(pg_get_functiondef(to_regprocedure($1)))where replace(%I,'' '','''')=replace($1,'' '','''')and %I=$2',t.name,c.hashcol,c.idcol,c.hashcol)using sig,before_hash;
  end loop;
 end loop;
 update greenloop_private.office_routines set original_hash=md5(pg_get_functiondef(sig::regprocedure))where to_regprocedure(implementation)=sig::regprocedure and original_hash=before_hash;
 update greenloop_private.capability_routines set original_hash=md5(pg_get_functiondef(sig::regprocedure))where to_regprocedure(implementation)=sig::regprocedure and original_hash=before_hash;
end;$patch$;
create or replace function greenloop_private.itc_read(p_imei text,p_offset integer,p_limit integer,p_expected_snapshot text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare data jsonb;result jsonb;dev uuid;begin
 perform greenloop_private.require_office_network();perform greenloop_private.pf_cap('imei_search','view');if p_offset is null or p_offset<0 or p_limit is null or p_limit not between 1 and 50 then raise exception 'Choose a valid 50-record correction page.'using errcode='22023';end if;
 data:=greenloop_private.ia_read(p_imei);if data->>'found'is distinct from 'true'then return jsonb_build_object('found',false);end if;
 select id into dev from public.devices where imei_1=data->'device'->>'imei_1'and deleted_at is null;result:=greenloop_private.itc_history(dev,p_offset,p_limit);if p_expected_snapshot is not null and p_expected_snapshot is distinct from result->>'snapshot'then raise exception 'Correction history changed. Search this IMEI again.'using errcode='40001';end if;return result||jsonb_build_object('imei',data->'device'->>'imei_1');
end;$$;
create or replace function public.get_imei_report_corrections_v1(p_imei text,p_offset integer default 0,p_limit integer default 50,p_expected_snapshot text default null)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$begin
 -- greenloop-office-wrapper-196
 perform greenloop_private.require_office_network();return greenloop_private.itc_read(p_imei,p_offset,p_limit,p_expected_snapshot);end;$$;
revoke all on function public.get_imei_report_corrections_v1(text,integer,integer,text)from public,anon;grant execute on function public.get_imei_report_corrections_v1(text,integer,integer,text)to authenticated;
do $$declare f record;begin for f in select oid::regprocedure::text sig from pg_proc where pronamespace='greenloop_private'::regnamespace and proname in('itc_value','itc_changes','itc_history','itc_enrich','itc_read')loop execute format('revoke all on function %s from public,anon,authenticated',f.sig);end loop;end;$$;
insert into greenloop_private.office_routines values('public.get_imei_report_corrections_v1(text,integer,integer,text)','greenloop_private.itc_read(text,integer,integer,text)',md5(pg_get_functiondef('greenloop_private.itc_read(text,integer,integer,text)'::regprocedure)),md5(pg_get_functiondef('public.get_imei_report_corrections_v1(text,integer,integer,text)'::regprocedure)))on conflict(identity)do update set implementation=excluded.implementation,original_hash=excluded.original_hash,wrapped_hash=excluded.wrapped_hash;
insert into greenloop_private.capability_rpc_rules values('get_imei_report_corrections_v1','{"page":"imei_search","capability":"view","read":true}'),('get_imei_qc_corrections_version','{"read":true}')on conflict(rpc_name)do update set rule=excluded.rule;
update greenloop_private.page_capability_installation set hash=(select md5(jsonb_agg(to_jsonb(r)order by rpc_name)::text)from greenloop_private.capability_rpc_rules r)where identity='rules';
create table if not exists greenloop_private.imei_qc_corrections_installation(identity text primary key,hash text not null);alter table greenloop_private.imei_qc_corrections_installation enable row level security;revoke all on greenloop_private.imei_qc_corrections_installation from public,anon,authenticated;
create or replace function public.get_imei_qc_corrections_version()returns text language sql stable security definer set search_path=pg_catalog,public as $$select case when public.get_imei_activity_journey_version()='20261109-imei-activity-1'and(select count(*)=8 and bool_and(coalesce(hash=md5(pg_get_functiondef(to_regprocedure(identity))),false))from greenloop_private.imei_qc_corrections_installation)and not exists(select 1 from pg_proc where pronamespace='greenloop_private'::regnamespace and proname in('itc_value','itc_changes','itc_history','itc_enrich','itc_read')and(has_function_privilege('authenticated',oid,'EXECUTE')or has_function_privilege('anon',oid,'EXECUTE')))and exists(select 1 from pg_class where oid='greenloop_private.imei_qc_corrections_installation'::regclass and relrowsecurity)and has_function_privilege('authenticated','public.get_imei_report_corrections_v1(text,integer,integer,text)','EXECUTE')and not has_function_privilege('anon','public.get_imei_report_corrections_v1(text,integer,integer,text)','EXECUTE')and not has_table_privilege('authenticated','greenloop_private.imei_qc_corrections_installation','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')and public.get_page_capabilities_version()='20261016-page-capabilities-1'then '20261114-imei-qc-corrections-1'end;$$;
revoke all on function public.get_imei_qc_corrections_version()from public;grant execute on function public.get_imei_qc_corrections_version()to anon,authenticated;
insert into greenloop_private.imei_qc_corrections_installation select sig,md5(pg_get_functiondef(sig::regprocedure))from unnest(array['greenloop_private.itc_value(text,jsonb,boolean)','greenloop_private.itc_changes(jsonb,jsonb,text,boolean,boolean)','greenloop_private.itc_history(uuid,integer,integer)','greenloop_private.itc_enrich(jsonb,uuid,uuid)','greenloop_private.itc_read(text,integer,integer,text)','greenloop_private.ia_read(text)','public.get_imei_report_corrections_v1(text,integer,integer,text)','public.get_imei_qc_corrections_version()'])sig on conflict(identity)do update set hash=excluded.hash;
do $$begin if public.get_imei_qc_corrections_version()is distinct from '20261114-imei-qc-corrections-1'then raise exception 'IMEI QC/corrections verification failed. Nothing installed.';end if;end;$$;
notify pgrst,'reload schema';
$ddl$;END;$imei_details_install$;
select public.get_imei_qc_corrections_version()as installed_imei_qc_corrections_version;
